def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals by start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [sorted_intervals[0]]

    for current_start, current_end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]

        if current_start <= last_end:
            # Overlapping or touching intervals - merge them
            merged[-1] = [last_start, max(last_end, current_end)]
        else:
            # Non-overlapping interval - add it to merged list
            merged.append([current_start, current_end])

    return merged

def toposort(nodes, edges):
    # Build adjacency list and in-degree count
    graph = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    # Process edges to build graph and count in-degrees
    for source, dest in edges:
        if source == dest:
            raise ValueError("Cycle detected")
        graph[source].append(dest)
        in_degree[dest] += 1

    # Find all nodes with zero in-degree
    zero_in_degree = []
    for node in nodes:
        if in_degree[node] == 0:
            zero_in_degree.append(node)

    # Sort to ensure lexicographic order
    zero_in_degree.sort()

    result = []

    while zero_in_degree:
        # Choose the smallest node
        current = zero_in_degree.pop(0)
        result.append(current)

        # Remove current node and update in-degrees
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                zero_in_degree.append(neighbor)

    # Check if all nodes were processed (no cycles)
    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("Limit must be positive")

    result = []
    current_batch = []
    current_weight = 0

    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("Weights must be positive and not exceed the limit")

        if current_weight + weight > limit:
            if current_batch:
                result.append(current_batch)
            current_batch = []
            current_weight = 0

        current_batch.append(name)
        current_weight += weight

    if current_batch:
        result.append(current_batch)

    return result

def parse_sse(chunks):
    buffer = b""
    events = []
    current_event = {}

    def process_line(line):
        if not line.startswith(b'data:'):
            return
        if b':' in line:
            key, value = line.split(b':', 1)
            value = value.lstrip()
        else:
            key, value = line, b""
        if key == b'data':
            current_event.setdefault(key, []).append(value)

    def process_buffer():
        lines = buffer.split(b'\n')
        for i, line in enumerate(lines):
            if i == len(lines) - 1 and not buffer.endswith(b'\n'):
                # Last line is incomplete
                return line
            if line.startswith(b'\r\n') or line == b'':
                # End of event
                if current_event.get(b'data'):
                    data_lines = current_event.get(b'data', [])
                    data = b'\n'.join(data_lines)
                    if data == b'[DONE]':
                        return None  # Stop processing
                    events.append(data.decode('utf-8'))
                current_event.clear()
            else:
                process_line(line)
        return b""

    for chunk in chunks:
        buffer += chunk
        result = process_buffer()
        if result is None:
            break
        buffer = result

    # Process remaining buffer
    if buffer:
        lines = buffer.split(b'\n')
        for i, line in enumerate(lines):
            if i == len(lines) - 1 and not buffer.endswith(b'\n'):
                # Incomplete final line, ignore
                pass
            elif line.startswith(b'\r\n') or line == b'':
                if current_event.get(b'data'):
                    data_lines = current_event.get(b'data', [])
                    data = b'\n'.join(data_lines)
                    if data == b'[DONE]':
                        break
                    events.append(data.decode('utf-8'))
                current_event.clear()
            else:
                process_line(line)

    return events

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("All arguments must be nonnegative")

    if attempt >= 30:  # 2^30 is already very large
        if base == 0:
            return cap if cap > 0 else 0.0
        else:
            # Handle overflow by checking if the result would exceed cap
            # For large exponents, we can't compute 2**attempt directly
            # but we know that for attempt >= 30, base * 2**attempt will be huge
            # unless base is 0 (which we already handled above)
            return cap

    # For reasonable values, compute the result directly
    if base == 0:
        return 0.0
    elif cap == 0:
        return 0.0
    else:
        result = base * (2 ** attempt)
        return min(cap, result)
